//! What the three Clients' emitters share: the generated-file headers, the
//! [`Error`] an emitter refuses a document with, and the operations' names
//! ([`name_operations`]), so `auth.verify2fa` names the same operation in
//! the TypeScript, Dart and Rust Clients, each in its own case.

use std::collections::BTreeMap;

use heck::{ToLowerCamelCase, ToUpperCamelCase};

use super::openapi::{Method, Operation};

/// The first line of every emitted TypeScript, Dart and Rust file.
pub(crate) const HEADER: &str =
    "// @generated by rok-data-sqlc from openapi.json. Do not edit by hand.\n";

/// The first line of every Client's emitted `README.md`.
pub(crate) const MARKDOWN_HEADER: &str =
    "<!-- @generated by rok-data-sqlc from openapi.json. Do not edit by hand. -->\n";

/// Why a Client cannot be emitted from a document the reader accepted.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Error(pub(crate) String);

impl std::fmt::Display for Error {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.0)
    }
}

impl std::error::Error for Error {}

/// An operation and the names the clients give it.
#[derive(Debug)]
pub(crate) struct Named<'a> {
    /// The operation.
    pub op: &'a Operation,
    /// The group it is under (`users`): its tag, in camelCase.
    pub group: String,
    /// Its name in the group (`update`): its `operationId` in camelCase,
    /// told apart by its path where two of a group share one.
    pub name: String,
}

impl Named<'_> {
    /// The name of the operation's query type: `UsersListQuery`.
    pub fn query_type(&self) -> String {
        format!(
            "{}{}Query",
            self.group.to_upper_camel_case(),
            self.name.to_upper_camel_case()
        )
    }

    /// Whether the operation is cached as a query: a `GET`.
    pub fn is_query(&self) -> bool {
        self.op.method == Method::Get
    }
}

/// The operations, each with its group and its name in the group.
///
/// utoipa names an operation after its handler, so two of a group may
/// share an `operationId` (`verify`, for `/auth/2fa/verify` and
/// `/auth/email/verify`): each of those is named after the first segment
/// where their paths part — `verify2fa`, `verifyEmail` — or, on one path,
/// its method.
pub(crate) fn name_operations(operations: &[Operation]) -> Vec<Named<'_>> {
    let mut named: Vec<Named<'_>> = operations
        .iter()
        .map(|op| Named {
            op,
            group: identifier(&op.tag.as_deref().unwrap_or("default").to_lower_camel_case()),
            name: identifier(&op.id.to_lower_camel_case()),
        })
        .collect();
    let mut groups: BTreeMap<(String, String), Vec<usize>> = BTreeMap::new();
    for (index, op) in named.iter().enumerate() {
        groups
            .entry((op.group.clone(), op.name.clone()))
            .or_default()
            .push(index);
    }
    for indices in groups.values().filter(|indices| indices.len() > 1) {
        let paths: Vec<Vec<&str>> = indices
            .iter()
            .map(|&index| segments(&named[index].op.path))
            .collect();
        let common = (0..)
            .take_while(|&at| {
                paths
                    .iter()
                    .all(|path| path.get(at).is_some() && path.get(at) == paths[0].get(at))
            })
            .count();
        for (&index, path) in indices.iter().zip(&paths) {
            let suffix = path
                .get(common)
                .map_or_else(|| named[index].op.method.as_str(), |segment| *segment);
            named[index].name = format!("{}{}", named[index].name, suffix.to_upper_camel_case());
        }
    }
    named
}

/// The path's segments that are not parameters.
fn segments(path: &str) -> Vec<&str> {
    path.split('/')
        .filter(|segment| !segment.is_empty() && !segment.starts_with('{'))
        .collect()
}

/// `name` as an identifier the clients' names start from (a TypeScript
/// identifier as it is): characters an identifier cannot hold become `_`,
/// and a leading digit gets one before it.
pub(crate) fn identifier(name: &str) -> String {
    let mut out: String = name
        .chars()
        .map(|c| {
            if c.is_ascii_alphanumeric() || c == '_' || c == '$' {
                c
            } else {
                '_'
            }
        })
        .collect();
    if out.is_empty() || out.starts_with(|c: char| c.is_ascii_digit()) {
        out.insert(0, '_');
    }
    out
}
